<template><view class="page"><PageHeader :title="post?post.title+' - 乌鸦crow look':'评论'" back-button/><template v-if="post"><image class="banner" :src="media(post.thumbnail)" mode="aspectFill"/><view class="article-heading"><CrowIcon name="description"/><text>{{post.title}}</text><button @click="openOriginal">原文</button></view><view class="section-heading"><view/><text>全部评论 <text class="count">{{post.comment_count||0}}条</text></text><view/></view><CommentList v-if="post.comments?.length" :comments="post.comments" reply @reply="reply"/><view v-else class="empty"><CrowIcon name="comment-o"/><text>暂无评论</text><button @click="write">我来聊几句</button></view></template><view v-else class="loading" @click="load">{{error||'加载中…'}}</view><view class="toolbar"><button class="input" @click="write"><image class="guest" src="/static/ui/guest.svg"/>我来聊几句</button><button aria-label="微信咨询" @click="service"><image src="/static/ui/wechat.svg"/></button><button aria-label="分享作品" @click="share"><image src="/static/ui/moments-outline.svg"/></button></view><CommentComposer v-model="composing" :post-id="id" :reply-to="replyingTo" @submitted="load"/></view></template>
<script setup>
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {request,media,service,shareUrl} from '../../lib/content';import PageHeader from '../../components/PageHeader.vue';import CrowIcon from '../../components/CrowIcon.vue';import CommentList from '../../components/CommentList.vue';import CommentComposer from '../../components/CommentComposer.vue';const post=ref(null),error=ref(''),composing=ref(false),replyingTo=ref(null),id=ref('');const load=async()=>{error.value='';try{post.value=(await request('post/get.json',{id:id.value},'post'+id.value)).post}catch(e){error.value=e.message}};onLoad(o=>{id.value=o.id;load()});const write=()=>{replyingTo.value=null;composing.value=true};const reply=comment=>{replyingTo.value=comment;composing.value=true};const openOriginal=()=>uni.navigateBack();const share=()=>post.value&&uni.setClipboardData({data:post.value.title+' '+shareUrl(id.value)})
</script>
<style scoped>.page{padding-bottom:100rpx}.banner{width:100%;height:320rpx;display:block}.article-heading{margin:30rpx 40rpx 20rpx;display:flex;align-items:center;gap:25rpx;font-size:20px}.article-heading>text:not(.crow-icon){font-size:18px;font-weight:500;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.article-heading button{background:#f3f3f3;font-size:14px;line-height:44rpx;padding:0 22rpx;margin:0;border-radius:8rpx}.section-heading{display:flex;gap:30rpx;align-items:center;margin-top:48rpx;font-size:16px;font-weight:700}.section-heading>view{height:1rpx;background:#eee;flex:1}.count{font-size:12px;font-weight:400;margin-left:12rpx}.toolbar{height:90rpx;position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1rpx solid #eee;padding:12rpx 40rpx;display:flex;gap:35rpx;align-items:center;z-index:30}.toolbar button{padding:0;background:transparent;font-size:24px;line-height:1;display:flex;align-items:center;margin:0;color:#555}.toolbar .input{flex:1;border-radius:50rpx;background:#f1f1f1;font-size:13px;color:#888;height:70rpx;gap:24rpx;padding:0 20rpx}.input .crow-icon{font-size:20px;color:#ccc}.toolbar image{width:40rpx;height:40rpx;filter:grayscale(1)}.empty{display:flex;align-items:center;flex-direction:column;margin-top:100rpx;color:#aaa;font-size:16px;font-weight:300;gap:35rpx}.empty>.crow-icon{font-size:80px;color:#ddd}.empty button{font-size:13px;background:transparent;font-weight:700}.loading{text-align:center;color:#aaa;margin:100rpx 0}:deep(.comments){padding-top:80rpx}.toolbar .input .guest{width:38rpx;height:38rpx}</style>
